@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #003B95;
  --blue: #006CE4;
  --gold: #FFB700;
  --gold-hover: #E5A500;
  --dark: #1a1a2e;
  --text: #1a1a2e;
  --text-secondary: #595959;
  --text-light: #6b7280;
  --bg: #ffffff;
  --bg-soft: #f5f7fa;
  --bg-warm: #fef7e0;
  --border: #e5e7eb;
  --border-light: #f0f0f0;
  --radius: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.15);
  --font-display: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'DM Sans', sans-serif;
  --transition: 0.2s ease;
  --max-w: 1200px;
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-body);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input, select { font-family: inherit; }
ul { list-style: none; }

.container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }

/* HEADER */
.header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
}
.logo {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.5px;
}
.logo span { color: var(--gold); }
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.header-actions .btn-ghost {
  color: #fff;
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}
.header-actions .btn-ghost:hover { background: rgba(255,255,255,0.1); }
.header-actions .btn-outline-white {
  color: #fff;
  border: 1px solid #fff;
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 500;
  transition: all var(--transition);
}
.header-actions .btn-outline-white:hover {
  background: #fff;
  color: var(--navy);
}

.nav-tabs {
  display: flex;
  gap: 4px;
  padding-bottom: 12px;
  overflow-x: auto;
}
.nav-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 24px;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition);
  border: 1px solid transparent;
}
.nav-tab:hover { border-color: rgba(255,255,255,0.5); }
.nav-tab.active {
  border-color: #fff;
  background: rgba(255,255,255,0.12);
}
.nav-tab svg { width: 20px; height: 20px; flex-shrink: 0; }

/* HERO */
.hero {
  background: var(--navy);
  padding: 32px 0 140px;
  position: relative;
}
.hero h1 {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 800;
  color: #fff;
  line-height: 1.15;
  margin-bottom: 8px;
  letter-spacing: -1px;
}
.hero .subtitle {
  font-size: 18px;
  color: rgba(255,255,255,0.85);
  margin-bottom: 32px;
}

/* SEARCH BAR */
.search-bar {
  background: var(--gold);
  padding: 4px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  gap: 4px;
  position: relative;
  margin-top: 8px;
}
.search-bar .field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fff;
  padding: 14px 16px;
  border-radius: 6px;
  font-size: 14px;
  min-width: 0;
}
.search-bar .field svg { color: var(--text-light); flex-shrink: 0; width: 20px; height: 20px; }
.search-bar .field input {
  border: none;
  outline: none;
  width: 100%;
  font-size: 14px;
  background: transparent;
  color: var(--text);
}
.search-bar .field input::placeholder { color: var(--text-light); }
.search-bar .btn-search {
  background: var(--blue);
  color: #fff;
  padding: 14px 28px;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}
.search-bar .btn-search:hover { background: #0057b8; }

.search-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 14px;
  margin-top: 12px;
}
.search-checkbox input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--blue);
}

/* RADIO GROUP */
.radio-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 20px;
}
.radio-group label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 14px;
  cursor: pointer;
}
.radio-group input[type="radio"] {
  width: 18px;
  height: 18px;
  accent-color: var(--blue);
}

/* SECTION COMMON */
.section {
  padding: 60px 0;
}
.section-alt { background: var(--bg-soft); }
.section-title {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 4px;
  letter-spacing: -0.5px;
  color: var(--text);
}
.section-subtitle {
  color: var(--text-secondary);
  font-size: 16px;
  margin-bottom: 28px;
}

/* TRUST BADGES */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: -80px;
  position: relative;
  z-index: 10;
}
.trust-badge {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-lg);
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
}
.trust-badge:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }
.trust-badge .icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #e8f0fe;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.trust-badge .icon-circle svg { width: 28px; height: 28px; color: var(--blue); }
.trust-badge h3 {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 6px;
}
.trust-badge p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }

/* OFFERS */
.offers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.offer-card {
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  overflow: hidden;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.offer-card.deals {
  background: linear-gradient(135deg, #003B95 0%, #0057b8 100%);
  color: #fff;
}
.offer-card.rewards {
  background: linear-gradient(135deg, #1a3a4a 0%, #2d5f73 100%);
  color: #fff;
}
.offer-card::before {
  content: '';
  position: absolute;
  top: -30px;
  right: -30px;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: rgba(255,255,255,0.06);
}
.offer-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 8px;
  position: relative;
}
.offer-card p {
  font-size: 14px;
  opacity: 0.9;
  margin-bottom: 20px;
  position: relative;
  line-height: 1.5;
}
.offer-card .btn-offer {
  display: inline-flex;
  background: var(--blue);
  color: #fff;
  padding: 10px 20px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  position: relative;
  width: fit-content;
  transition: background var(--transition);
}
.offer-card .btn-offer:hover { background: #0057b8; }
.offer-card.rewards .btn-offer { background: var(--gold); color: var(--dark); }
.offer-card.rewards .btn-offer:hover { background: var(--gold-hover); }

/* PROPERTY TYPES SCROLL */
.property-scroll {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 8px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}
.property-scroll::-webkit-scrollbar { height: 4px; }
.property-scroll::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.property-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
.property-type-chip {
  padding: 10px 20px;
  border-radius: 24px;
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  scroll-snap-align: start;
  transition: all var(--transition);
  color: var(--text);
  background: #fff;
}
.property-type-chip:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* TABS */
.tab-bar {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  margin-bottom: 28px;
  border-bottom: 2px solid var(--border-light);
  padding-bottom: 0;
}
.tab-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--blue); }
.tab-btn.active {
  color: var(--blue);
  border-bottom-color: var(--blue);
  font-weight: 600;
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* DEST CARDS */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.dest-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-md);
}
.dest-card-img {
  width: 64px;
  height: 64px;
  border-radius: 8px;
  background: linear-gradient(135deg, #e8f0fe, #b3d4ff);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}
.dest-card h4 { font-size: 15px; font-weight: 600; }
.dest-card p { font-size: 13px; color: var(--text-light); margin-top: 2px; }

/* CAROUSEL */
.carousel-wrap { position: relative; }
.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 8px 0 16px;
  scroll-behavior: smooth;
}
.carousel::-webkit-scrollbar { height: 4px; }
.carousel::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.carousel::-webkit-scrollbar-thumb { background: #c4c4c4; border-radius: 4px; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #fff;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition);
  border: 1px solid var(--border);
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--bg-soft); }
.carousel-btn.prev { left: -16px; }
.carousel-btn.next { right: -16px; }
.carousel-btn svg { width: 20px; height: 20px; color: var(--text); }

/* PROPERTY CARD */
.property-card {
  min-width: 260px;
  max-width: 260px;
  scroll-snap-align: start;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.property-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.property-card-img {
  height: 180px;
  background: linear-gradient(135deg, #c8d6e5, #8395a7);
  position: relative;
}
.property-card-img .badge-deal {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #00800d;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 4px;
}
.property-card-body { padding: 16px; }
.property-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.property-card-body .location { font-size: 13px; color: var(--text-light); margin-bottom: 10px; }
.property-card-body .rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
}
.rating-badge {
  background: var(--navy);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 6px 6px 6px 0;
}
.rating-text { font-size: 13px; font-weight: 500; }
.rating-count { font-size: 12px; color: var(--text-light); }
.property-card-body .price {
  text-align: right;
  margin-top: 8px;
}
.price .original { text-decoration: line-through; color: var(--text-light); font-size: 13px; margin-right: 6px; }
.price .current { font-size: 18px; font-weight: 700; color: var(--text); }
.price .nights { display: block; font-size: 12px; color: var(--text-light); margin-top: 2px; }

/* TRENDING */
.trending-grid {
  display: flex;
  gap: 16px;
}
.trending-card {
  flex: 1;
  height: 200px;
  border-radius: var(--radius-lg);
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #003B95 0%, #4a7fd4 100%);
  transition: transform var(--transition);
}
.trending-card:hover { transform: scale(1.02); }
.trending-card:nth-child(1) { flex: 2; height: 220px; }
.trending-card:nth-child(2) { flex: 2; height: 220px; }
.trending-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(0,0,0,0.6), transparent);
  color: #fff;
}
.trending-card-content h3 { font-family: var(--font-display); font-size: 20px; font-weight: 700; }
.trending-flag { font-size: 28px; position: absolute; top: 16px; right: 16px; }

/* EXPLORE GRID */
.explore-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.explore-card {
  border-radius: var(--radius);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}
.explore-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.explore-card-img {
  height: 140px;
  background: linear-gradient(135deg, #8395a7, #576574);
  position: relative;
}
.explore-card-body {
  padding: 12px;
  background: #fff;
  border: 1px solid var(--border);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}
.explore-card-body h4 { font-size: 15px; font-weight: 600; }
.explore-card-body p { font-size: 13px; color: var(--text-light); }

/* WEEKEND DEALS / HOMES */
.deals-scroll {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding-bottom: 16px;
  scroll-snap-type: x mandatory;
}
.deals-scroll::-webkit-scrollbar { height: 4px; }
.deals-scroll::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.deals-scroll::-webkit-scrollbar-thumb { background: #c4c4c4; border-radius: 4px; }

.deal-card {
  min-width: 280px;
  max-width: 280px;
  scroll-snap-align: start;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.deal-card-img {
  height: 180px;
  background: linear-gradient(135deg, #c8d6e5, #8395a7);
  position: relative;
}
.deal-card-body { padding: 16px; }
.deal-card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 2px; }
.deal-card-body .location { font-size: 13px; color: var(--text-light); margin-bottom: 10px; }
.deal-card-body .rating { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; }
.deal-card-body .duration { font-size: 13px; color: var(--text-secondary); margin-bottom: 6px; }

/* LOYALTY CTA */
.loyalty-section {
  background: linear-gradient(135deg, var(--navy) 0%, #1a4fad 60%, #2563eb 100%);
  padding: 60px 0;
  position: relative;
  overflow: hidden;
}
.loyalty-section::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: rgba(255,255,255,0.04);
}
.loyalty-content {
  max-width: 600px;
  color: #fff;
  position: relative;
}
.loyalty-content h2 {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 800;
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}
.loyalty-content h3 {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 12px;
  opacity: 0.9;
}
.loyalty-content p { font-size: 16px; opacity: 0.85; margin-bottom: 28px; line-height: 1.6; }
.loyalty-actions { display: flex; gap: 12px; }
.btn-gold {
  background: var(--gold);
  color: var(--dark);
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 15px;
  font-weight: 600;
  transition: background var(--transition);
  display: inline-block;
}
.btn-gold:hover { background: var(--gold-hover); }
.btn-white-outline {
  border: 2px solid #fff;
  color: #fff;
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 15px;
  font-weight: 600;
  transition: all var(--transition);
  display: inline-block;
}
.btn-white-outline:hover { background: #fff; color: var(--navy); }

/* POPULAR LINKS */
.popular-links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.popular-links-grid a {
  display: inline-block;
  padding: 8px 16px;
  border: 1px solid var(--border);
  border-radius: 24px;
  font-size: 13px;
  color: var(--text);
  transition: all var(--transition);
}
.popular-links-grid a:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* FOOTER */
.footer {
  background: #0a1628;
  color: #fff;
  padding: 60px 0 30px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: rgba(255,255,255,0.7);
}
.footer-col a {
  display: block;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  text-align: center;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
}

/* BENEFITS */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  background: #fff;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.benefit-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.benefit-card .icon-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: #e8f0fe;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.benefit-card .icon-circle svg { width: 28px; height: 28px; color: var(--blue); }
.benefit-card h3 { font-family: var(--font-display); font-size: 17px; font-weight: 700; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.5; }

/* PACKAGE DEST */
.pkg-dest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.pkg-dest-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  transition: all var(--transition);
  background: #fff;
}
.pkg-dest-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }
.pkg-dest-card-img {
  height: 160px;
  background: linear-gradient(135deg, #4ecdc4, #2d98da);
}
.pkg-dest-card-body { padding: 16px; }
.pkg-dest-card-body h4 { font-size: 16px; font-weight: 600; }
.pkg-dest-card-body .country { font-size: 13px; color: var(--text-light); margin-top: 2px; }
.pkg-dest-card-body .props { font-size: 13px; color: var(--text-secondary); margin-top: 8px; }

/* RENTAL COMPANIES */
.companies-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 16px;
}
.company-card {
  height: 80px;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 16px;
  color: var(--text);
  transition: all var(--transition);
}
.company-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-sm);
}

/* CREDIT CARD PROMO */
.promo-banner {
  background: linear-gradient(135deg, #1a3a4a, #2d5f73);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.promo-banner h3 { font-family: var(--font-display); font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.promo-banner p { opacity: 0.9; font-size: 14px; }
.promo-banner .btn-offer {
  background: var(--gold);
  color: var(--dark);
  padding: 12px 24px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
  transition: background var(--transition);
}
.promo-banner .btn-offer:hover { background: var(--gold-hover); }

/* FAQ ACCORDION */
.faq-list { max-width: 800px; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 20px 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.faq-question:hover { color: var(--blue); }
.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 200px; }
.faq-answer p {
  padding-bottom: 20px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* RENTAL DEST TABLE */
.rental-dest-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.rental-dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  transition: all var(--transition);
}
.rental-dest-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-sm);
}
.rental-dest-card-img {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  background: linear-gradient(135deg, #e8f0fe, #b3d4ff);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.rental-dest-info h4 { font-size: 15px; font-weight: 600; }
.rental-dest-info p { font-size: 13px; color: var(--text-light); }
.rental-dest-info .price-tag { font-size: 14px; font-weight: 600; color: var(--blue); margin-top: 2px; }

/* ATTRACTION CARDS */
.activity-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  background: #fff;
  transition: all var(--transition);
}
.activity-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.activity-card-img {
  height: 180px;
  background: linear-gradient(135deg, #ffa502, #ff6348);
  position: relative;
}
.activity-card-body { padding: 16px; }
.activity-card-body h4 { font-size: 14px; font-weight: 600; line-height: 1.4; }

.activity-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

/* NEARBY */
.nearby-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.nearby-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  height: 200px;
  background: linear-gradient(135deg, #576574, #222f3e);
  transition: transform var(--transition);
}
.nearby-card:hover { transform: scale(1.02); }
.nearby-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
  color: #fff;
}
.nearby-card-content h4 { font-family: var(--font-display); font-size: 18px; font-weight: 700; }
.nearby-card-content p { font-size: 13px; opacity: 0.85; }

/* ACCOUNT CTA */
.account-cta {
  background: linear-gradient(135deg, var(--navy) 0%, #1a4fad 100%);
  border-radius: var(--radius-lg);
  padding: 48px;
  color: #fff;
  text-align: center;
}
.account-cta h2 { font-family: var(--font-display); font-size: 32px; font-weight: 800; margin-bottom: 8px; }
.account-cta h3 { font-size: 18px; opacity: 0.9; margin-bottom: 12px; }
.account-cta p { font-size: 15px; opacity: 0.8; margin-bottom: 28px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* PILL LINKS (for popular things to do) */
.pill-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.pill-links a {
  display: inline-block;
  padding: 8px 18px;
  border: 1px solid var(--border);
  border-radius: 24px;
  font-size: 13px;
  transition: all var(--transition);
}
.pill-links a:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* IMAGE PLACEHOLDERS */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  color: rgba(255,255,255,0.6);
}

/* MOBILE */
@media (max-width: 1024px) {
  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .explore-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .rental-dest-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .hero h1 { font-size: 32px; }
  .hero .subtitle { font-size: 15px; }
  .hero { padding-bottom: 100px; }
  .search-bar { flex-direction: column; }
  .search-bar .field { width: 100%; }
  .search-bar .btn-search { width: 100%; text-align: center; }
  .trust-badges { grid-template-columns: 1fr 1fr; margin-top: -60px; gap: 12px; }
  .trust-badge { padding: 20px 16px; }
  .offers-grid { grid-template-columns: 1fr; }
  .section-title { font-size: 22px; }
  .section-subtitle { font-size: 14px; }
  .trending-grid { flex-direction: column; }
  .trending-card, .trending-card:nth-child(1), .trending-card:nth-child(2) { height: 180px; }
  .explore-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .pkg-dest-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .loyalty-content h2 { font-size: 28px; }
  .promo-banner { flex-direction: column; text-align: center; }
  .radio-group { flex-direction: column; gap: 10px; }
  .companies-grid { grid-template-columns: repeat(3, 1fr); }
  .account-cta { padding: 32px 24px; }
  .account-cta h2 { font-size: 24px; }
  .nearby-grid { grid-template-columns: 1fr; }
  .activity-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-tabs { gap: 2px; }
  .nav-tab { padding: 8px 12px; font-size: 13px; }
  .header-actions .btn-ghost, .header-actions .btn-outline-white { padding: 6px 10px; font-size: 13px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 26px; }
  .trust-badges { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .loyalty-actions { flex-direction: column; }
  .dest-grid { grid-template-columns: 1fr; }
  .activity-grid { grid-template-columns: 1fr; }
}

/* ANIMATIONS */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  animation: fadeInUp 0.5s ease forwards;
  opacity: 0;
}
.animate-in:nth-child(2) { animation-delay: 0.1s; }
.animate-in:nth-child(3) { animation-delay: 0.2s; }
.animate-in:nth-child(4) { animation-delay: 0.3s; }

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #003B95;
  --blue: #006CE4;
  --gold: #FFB700;
  --gold-hover: #E5A500;
  --dark: #1a1a2e;
  --text: #1a1a2e;
  --text-secondary: #595959;
  --text-light: #6b7280;
  --bg: #ffffff;
  --bg-soft: #f5f7fa;
  --bg-warm: #fef7e0;
  --border: #e5e7eb;
  --border-light: #f0f0f0;
  --radius: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.15);
  --font-display: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'DM Sans', sans-serif;
  --transition: 0.2s ease;
  --max-w: 1200px;
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-body);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input, select { font-family: inherit; }
ul { list-style: none; }

.container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }

/* HEADER */
.header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
}
.logo {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.5px;
}
.logo span { color: var(--gold); }
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.header-actions .btn-ghost {
  color: #fff;
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}
.header-actions .btn-ghost:hover { background: rgba(255,255,255,0.1); }
.header-actions .btn-outline-white {
  color: #fff;
  border: 1px solid #fff;
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 500;
  transition: all var(--transition);
}
.header-actions .btn-outline-white:hover {
  background: #fff;
  color: var(--navy);
}

.nav-tabs {
  display: flex;
  gap: 4px;
  padding-bottom: 12px;
  overflow-x: auto;
}
.nav-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 24px;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition);
  border: 1px solid transparent;
}
.nav-tab:hover { border-color: rgba(255,255,255,0.5); }
.nav-tab.active {
  border-color: #fff;
  background: rgba(255,255,255,0.12);
}
.nav-tab svg { width: 20px; height: 20px; flex-shrink: 0; }

/* HERO */
.hero {
  background: var(--navy);
  padding: 32px 0 140px;
  position: relative;
}
.hero h1 {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 800;
  color: #fff;
  line-height: 1.15;
  margin-bottom: 8px;
  letter-spacing: -1px;
}
.hero .subtitle {
  font-size: 18px;
  color: rgba(255,255,255,0.85);
  margin-bottom: 32px;
}

/* SEARCH BAR */
.search-bar {
  background: var(--gold);
  padding: 4px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  gap: 4px;
  position: relative;
  margin-top: 8px;
}
.search-bar .field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fff;
  padding: 14px 16px;
  border-radius: 6px;
  font-size: 14px;
  min-width: 0;
}
.search-bar .field svg { color: var(--text-light); flex-shrink: 0; width: 20px; height: 20px; }
.search-bar .field input {
  border: none;
  outline: none;
  width: 100%;
  font-size: 14px;
  background: transparent;
  color: var(--text);
}
.search-bar .field input::placeholder { color: var(--text-light); }
.search-bar .btn-search {
  background: var(--blue);
  color: #fff;
  padding: 14px 28px;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}
.search-bar .btn-search:hover { background: #0057b8; }

.search-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 14px;
  margin-top: 12px;
}
.search-checkbox input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--blue);
}

/* RADIO GROUP */
.radio-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 20px;
}
.radio-group label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 14px;
  cursor: pointer;
}
.radio-group input[type="radio"] {
  width: 18px;
  height: 18px;
  accent-color: var(--blue);
}

/* SECTION COMMON */
.section {
  padding: 60px 0;
}
.section-alt { background: var(--bg-soft); }
.section-title {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 4px;
  letter-spacing: -0.5px;
  color: var(--text);
}
.section-subtitle {
  color: var(--text-secondary);
  font-size: 16px;
  margin-bottom: 28px;
}

/* TRUST BADGES */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: -80px;
  position: relative;
  z-index: 10;
}
.trust-badge {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-lg);
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
}
.trust-badge:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }
.trust-badge .icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #e8f0fe;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.trust-badge .icon-circle svg { width: 28px; height: 28px; color: var(--blue); }
.trust-badge h3 {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 6px;
}
.trust-badge p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }

/* OFFERS */
.offers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.offer-card {
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  overflow: hidden;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.offer-card.deals {
  background: linear-gradient(135deg, #003B95 0%, #0057b8 100%);
  color: #fff;
}
.offer-card.rewards {
  background: linear-gradient(135deg, #1a3a4a 0%, #2d5f73 100%);
  color: #fff;
}
.offer-card::before {
  content: '';
  position: absolute;
  top: -30px;
  right: -30px;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: rgba(255,255,255,0.06);
}
.offer-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 8px;
  position: relative;
}
.offer-card p {
  font-size: 14px;
  opacity: 0.9;
  margin-bottom: 20px;
  position: relative;
  line-height: 1.5;
}
.offer-card .btn-offer {
  display: inline-flex;
  background: var(--blue);
  color: #fff;
  padding: 10px 20px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  position: relative;
  width: fit-content;
  transition: background var(--transition);
}
.offer-card .btn-offer:hover { background: #0057b8; }
.offer-card.rewards .btn-offer { background: var(--gold); color: var(--dark); }
.offer-card.rewards .btn-offer:hover { background: var(--gold-hover); }

/* PROPERTY TYPES SCROLL */
.property-scroll {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 8px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}
.property-scroll::-webkit-scrollbar { height: 4px; }
.property-scroll::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.property-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
.property-type-chip {
  padding: 10px 20px;
  border-radius: 24px;
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  scroll-snap-align: start;
  transition: all var(--transition);
  color: var(--text);
  background: #fff;
}
.property-type-chip:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* TABS */
.tab-bar {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  margin-bottom: 28px;
  border-bottom: 2px solid var(--border-light);
  padding-bottom: 0;
}
.tab-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--blue); }
.tab-btn.active {
  color: var(--blue);
  border-bottom-color: var(--blue);
  font-weight: 600;
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* DEST CARDS */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.dest-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-md);
}
.dest-card-img {
  width: 64px;
  height: 64px;
  border-radius: 8px;
  background: linear-gradient(135deg, #e8f0fe, #b3d4ff);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}
.dest-card h4 { font-size: 15px; font-weight: 600; }
.dest-card p { font-size: 13px; color: var(--text-light); margin-top: 2px; }

/* CAROUSEL */
.carousel-wrap { position: relative; }
.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 8px 0 16px;
  scroll-behavior: smooth;
}
.carousel::-webkit-scrollbar { height: 4px; }
.carousel::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.carousel::-webkit-scrollbar-thumb { background: #c4c4c4; border-radius: 4px; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #fff;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition);
  border: 1px solid var(--border);
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--bg-soft); }
.carousel-btn.prev { left: -16px; }
.carousel-btn.next { right: -16px; }
.carousel-btn svg { width: 20px; height: 20px; color: var(--text); }

/* PROPERTY CARD */
.property-card {
  min-width: 260px;
  max-width: 260px;
  scroll-snap-align: start;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.property-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.property-card-img {
  height: 180px;
  background: linear-gradient(135deg, #c8d6e5, #8395a7);
  position: relative;
}
.property-card-img .badge-deal {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #00800d;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 4px;
}
.property-card-body { padding: 16px; }
.property-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.property-card-body .location { font-size: 13px; color: var(--text-light); margin-bottom: 10px; }
.property-card-body .rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
}
.rating-badge {
  background: var(--navy);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 6px 6px 6px 0;
}
.rating-text { font-size: 13px; font-weight: 500; }
.rating-count { font-size: 12px; color: var(--text-light); }
.property-card-body .price {
  text-align: right;
  margin-top: 8px;
}
.price .original { text-decoration: line-through; color: var(--text-light); font-size: 13px; margin-right: 6px; }
.price .current { font-size: 18px; font-weight: 700; color: var(--text); }
.price .nights { display: block; font-size: 12px; color: var(--text-light); margin-top: 2px; }

/* TRENDING */
.trending-grid {
  display: flex;
  gap: 16px;
}
.trending-card {
  flex: 1;
  height: 200px;
  border-radius: var(--radius-lg);
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #003B95 0%, #4a7fd4 100%);
  transition: transform var(--transition);
}
.trending-card:hover { transform: scale(1.02); }
.trending-card:nth-child(1) { flex: 2; height: 220px; }
.trending-card:nth-child(2) { flex: 2; height: 220px; }
.trending-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(0,0,0,0.6), transparent);
  color: #fff;
}
.trending-card-content h3 { font-family: var(--font-display); font-size: 20px; font-weight: 700; }
.trending-flag { font-size: 28px; position: absolute; top: 16px; right: 16px; }

/* EXPLORE GRID */
.explore-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.explore-card {
  border-radius: var(--radius);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}
.explore-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.explore-card-img {
  height: 140px;
  background: linear-gradient(135deg, #8395a7, #576574);
  position: relative;
}
.explore-card-body {
  padding: 12px;
  background: #fff;
  border: 1px solid var(--border);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}
.explore-card-body h4 { font-size: 15px; font-weight: 600; }
.explore-card-body p { font-size: 13px; color: var(--text-light); }

/* WEEKEND DEALS / HOMES */
.deals-scroll {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding-bottom: 16px;
  scroll-snap-type: x mandatory;
}
.deals-scroll::-webkit-scrollbar { height: 4px; }
.deals-scroll::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.deals-scroll::-webkit-scrollbar-thumb { background: #c4c4c4; border-radius: 4px; }

.deal-card {
  min-width: 280px;
  max-width: 280px;
  scroll-snap-align: start;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.deal-card-img {
  height: 180px;
  background: linear-gradient(135deg, #c8d6e5, #8395a7);
  position: relative;
}
.deal-card-body { padding: 16px; }
.deal-card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 2px; }
.deal-card-body .location { font-size: 13px; color: var(--text-light); margin-bottom: 10px; }
.deal-card-body .rating { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; }
.deal-card-body .duration { font-size: 13px; color: var(--text-secondary); margin-bottom: 6px; }

/* LOYALTY CTA */
.loyalty-section {
  background: linear-gradient(135deg, var(--navy) 0%, #1a4fad 60%, #2563eb 100%);
  padding: 60px 0;
  position: relative;
  overflow: hidden;
}
.loyalty-section::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: rgba(255,255,255,0.04);
}
.loyalty-content {
  max-width: 600px;
  color: #fff;
  position: relative;
}
.loyalty-content h2 {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 800;
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}
.loyalty-content h3 {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 12px;
  opacity: 0.9;
}
.loyalty-content p { font-size: 16px; opacity: 0.85; margin-bottom: 28px; line-height: 1.6; }
.loyalty-actions { display: flex; gap: 12px; }
.btn-gold {
  background: var(--gold);
  color: var(--dark);
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 15px;
  font-weight: 600;
  transition: background var(--transition);
  display: inline-block;
}
.btn-gold:hover { background: var(--gold-hover); }
.btn-white-outline {
  border: 2px solid #fff;
  color: #fff;
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 15px;
  font-weight: 600;
  transition: all var(--transition);
  display: inline-block;
}
.btn-white-outline:hover { background: #fff; color: var(--navy); }

/* POPULAR LINKS */
.popular-links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.popular-links-grid a {
  display: inline-block;
  padding: 8px 16px;
  border: 1px solid var(--border);
  border-radius: 24px;
  font-size: 13px;
  color: var(--text);
  transition: all var(--transition);
}
.popular-links-grid a:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* FOOTER */
.footer {
  background: #0a1628;
  color: #fff;
  padding: 60px 0 30px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: rgba(255,255,255,0.7);
}
.footer-col a {
  display: block;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  text-align: center;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
}

/* BENEFITS */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  background: #fff;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.benefit-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.benefit-card .icon-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: #e8f0fe;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.benefit-card .icon-circle svg { width: 28px; height: 28px; color: var(--blue); }
.benefit-card h3 { font-family: var(--font-display); font-size: 17px; font-weight: 700; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.5; }

/* PACKAGE DEST */
.pkg-dest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.pkg-dest-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  transition: all var(--transition);
  background: #fff;
}
.pkg-dest-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }
.pkg-dest-card-img {
  height: 160px;
  background: linear-gradient(135deg, #4ecdc4, #2d98da);
}
.pkg-dest-card-body { padding: 16px; }
.pkg-dest-card-body h4 { font-size: 16px; font-weight: 600; }
.pkg-dest-card-body .country { font-size: 13px; color: var(--text-light); margin-top: 2px; }
.pkg-dest-card-body .props { font-size: 13px; color: var(--text-secondary); margin-top: 8px; }

/* RENTAL COMPANIES */
.companies-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 16px;
}
.company-card {
  height: 80px;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 16px;
  color: var(--text);
  transition: all var(--transition);
}
.company-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-sm);
}

/* CREDIT CARD PROMO */
.promo-banner {
  background: linear-gradient(135deg, #1a3a4a, #2d5f73);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.promo-banner h3 { font-family: var(--font-display); font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.promo-banner p { opacity: 0.9; font-size: 14px; }
.promo-banner .btn-offer {
  background: var(--gold);
  color: var(--dark);
  padding: 12px 24px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
  transition: background var(--transition);
}
.promo-banner .btn-offer:hover { background: var(--gold-hover); }

/* FAQ ACCORDION */
.faq-list { max-width: 800px; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 20px 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.faq-question:hover { color: var(--blue); }
.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 200px; }
.faq-answer p {
  padding-bottom: 20px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* RENTAL DEST TABLE */
.rental-dest-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.rental-dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  transition: all var(--transition);
}
.rental-dest-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-sm);
}
.rental-dest-card-img {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  background: linear-gradient(135deg, #e8f0fe, #b3d4ff);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.rental-dest-info h4 { font-size: 15px; font-weight: 600; }
.rental-dest-info p { font-size: 13px; color: var(--text-light); }
.rental-dest-info .price-tag { font-size: 14px; font-weight: 600; color: var(--blue); margin-top: 2px; }

/* ATTRACTION CARDS */
.activity-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  background: #fff;
  transition: all var(--transition);
}
.activity-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.activity-card-img {
  height: 180px;
  background: linear-gradient(135deg, #ffa502, #ff6348);
  position: relative;
}
.activity-card-body { padding: 16px; }
.activity-card-body h4 { font-size: 14px; font-weight: 600; line-height: 1.4; }

.activity-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

/* NEARBY */
.nearby-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.nearby-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  height: 200px;
  background: linear-gradient(135deg, #576574, #222f3e);
  transition: transform var(--transition);
}
.nearby-card:hover { transform: scale(1.02); }
.nearby-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
  color: #fff;
}
.nearby-card-content h4 { font-family: var(--font-display); font-size: 18px; font-weight: 700; }
.nearby-card-content p { font-size: 13px; opacity: 0.85; }

/* ACCOUNT CTA */
.account-cta {
  background: linear-gradient(135deg, var(--navy) 0%, #1a4fad 100%);
  border-radius: var(--radius-lg);
  padding: 48px;
  color: #fff;
  text-align: center;
}
.account-cta h2 { font-family: var(--font-display); font-size: 32px; font-weight: 800; margin-bottom: 8px; }
.account-cta h3 { font-size: 18px; opacity: 0.9; margin-bottom: 12px; }
.account-cta p { font-size: 15px; opacity: 0.8; margin-bottom: 28px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* PILL LINKS (for popular things to do) */
.pill-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.pill-links a {
  display: inline-block;
  padding: 8px 18px;
  border: 1px solid var(--border);
  border-radius: 24px;
  font-size: 13px;
  transition: all var(--transition);
}
.pill-links a:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* IMAGE PLACEHOLDERS */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  color: rgba(255,255,255,0.6);
}

/* MOBILE */
@media (max-width: 1024px) {
  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .explore-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .rental-dest-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .hero h1 { font-size: 32px; }
  .hero .subtitle { font-size: 15px; }
  .hero { padding-bottom: 100px; }
  .search-bar { flex-direction: column; }
  .search-bar .field { width: 100%; }
  .search-bar .btn-search { width: 100%; text-align: center; }
  .trust-badges { grid-template-columns: 1fr 1fr; margin-top: -60px; gap: 12px; }
  .trust-badge { padding: 20px 16px; }
  .offers-grid { grid-template-columns: 1fr; }
  .section-title { font-size: 22px; }
  .section-subtitle { font-size: 14px; }
  .trending-grid { flex-direction: column; }
  .trending-card, .trending-card:nth-child(1), .trending-card:nth-child(2) { height: 180px; }
  .explore-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .pkg-dest-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .loyalty-content h2 { font-size: 28px; }
  .promo-banner { flex-direction: column; text-align: center; }
  .radio-group { flex-direction: column; gap: 10px; }
  .companies-grid { grid-template-columns: repeat(3, 1fr); }
  .account-cta { padding: 32px 24px; }
  .account-cta h2 { font-size: 24px; }
  .nearby-grid { grid-template-columns: 1fr; }
  .activity-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-tabs { gap: 2px; }
  .nav-tab { padding: 8px 12px; font-size: 13px; }
  .header-actions .btn-ghost, .header-actions .btn-outline-white { padding: 6px 10px; font-size: 13px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 26px; }
  .trust-badges { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .loyalty-actions { flex-direction: column; }
  .dest-grid { grid-template-columns: 1fr; }
  .activity-grid { grid-template-columns: 1fr; }
}

/* ANIMATIONS */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  animation: fadeInUp 0.5s ease forwards;
  opacity: 0;
}
.animate-in:nth-child(2) { animation-delay: 0.1s; }
.animate-in:nth-child(3) { animation-delay: 0.2s; }
.animate-in:nth-child(4) { animation-delay: 0.3s; }

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #003B95;
  --blue: #006CE4;
  --gold: #FFB700;
  --gold-hover: #E5A500;
  --dark: #1a1a2e;
  --text: #1a1a2e;
  --text-secondary: #595959;
  --text-light: #6b7280;
  --bg: #ffffff;
  --bg-soft: #f5f7fa;
  --bg-warm: #fef7e0;
  --border: #e5e7eb;
  --border-light: #f0f0f0;
  --radius: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.15);
  --font-display: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'DM Sans', sans-serif;
  --transition: 0.2s ease;
  --max-w: 1200px;
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-body);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input, select { font-family: inherit; }
ul { list-style: none; }

.container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }

/* HEADER */
.header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
}
.logo {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.5px;
}
.logo span { color: var(--gold); }
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.header-actions .btn-ghost {
  color: #fff;
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 500;
  transition: background var(--transition);
}
.header-actions .btn-ghost:hover { background: rgba(255,255,255,0.1); }
.header-actions .btn-outline-white {
  color: #fff;
  border: 1px solid #fff;
  padding: 8px 16px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 500;
  transition: all var(--transition);
}
.header-actions .btn-outline-white:hover {
  background: #fff;
  color: var(--navy);
}

.nav-tabs {
  display: flex;
  gap: 4px;
  padding-bottom: 12px;
  overflow-x: auto;
}
.nav-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 24px;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all var(--transition);
  border: 1px solid transparent;
}
.nav-tab:hover { border-color: rgba(255,255,255,0.5); }
.nav-tab.active {
  border-color: #fff;
  background: rgba(255,255,255,0.12);
}
.nav-tab svg { width: 20px; height: 20px; flex-shrink: 0; }

/* HERO */
.hero {
  background: var(--navy);
  padding: 32px 0 140px;
  position: relative;
}
.hero h1 {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 800;
  color: #fff;
  line-height: 1.15;
  margin-bottom: 8px;
  letter-spacing: -1px;
}
.hero .subtitle {
  font-size: 18px;
  color: rgba(255,255,255,0.85);
  margin-bottom: 32px;
}

/* SEARCH BAR */
.search-bar {
  background: var(--gold);
  padding: 4px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  gap: 4px;
  position: relative;
  margin-top: 8px;
}
.search-bar .field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fff;
  padding: 14px 16px;
  border-radius: 6px;
  font-size: 14px;
  min-width: 0;
}
.search-bar .field svg { color: var(--text-light); flex-shrink: 0; width: 20px; height: 20px; }
.search-bar .field input {
  border: none;
  outline: none;
  width: 100%;
  font-size: 14px;
  background: transparent;
  color: var(--text);
}
.search-bar .field input::placeholder { color: var(--text-light); }
.search-bar .btn-search {
  background: var(--blue);
  color: #fff;
  padding: 14px 28px;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}
.search-bar .btn-search:hover { background: #0057b8; }

.search-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 14px;
  margin-top: 12px;
}
.search-checkbox input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--blue);
}

/* RADIO GROUP */
.radio-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 20px;
}
.radio-group label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 14px;
  cursor: pointer;
}
.radio-group input[type="radio"] {
  width: 18px;
  height: 18px;
  accent-color: var(--blue);
}

/* SECTION COMMON */
.section {
  padding: 60px 0;
}
.section-alt { background: var(--bg-soft); }
.section-title {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 4px;
  letter-spacing: -0.5px;
  color: var(--text);
}
.section-subtitle {
  color: var(--text-secondary);
  font-size: 16px;
  margin-bottom: 28px;
}

/* TRUST BADGES */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: -80px;
  position: relative;
  z-index: 10;
}
.trust-badge {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-lg);
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
}
.trust-badge:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }
.trust-badge .icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #e8f0fe;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.trust-badge .icon-circle svg { width: 28px; height: 28px; color: var(--blue); }
.trust-badge h3 {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 6px;
}
.trust-badge p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }

/* OFFERS */
.offers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.offer-card {
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  overflow: hidden;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.offer-card.deals {
  background: linear-gradient(135deg, #003B95 0%, #0057b8 100%);
  color: #fff;
}
.offer-card.rewards {
  background: linear-gradient(135deg, #1a3a4a 0%, #2d5f73 100%);
  color: #fff;
}
.offer-card::before {
  content: '';
  position: absolute;
  top: -30px;
  right: -30px;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: rgba(255,255,255,0.06);
}
.offer-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 8px;
  position: relative;
}
.offer-card p {
  font-size: 14px;
  opacity: 0.9;
  margin-bottom: 20px;
  position: relative;
  line-height: 1.5;
}
.offer-card .btn-offer {
  display: inline-flex;
  background: var(--blue);
  color: #fff;
  padding: 10px 20px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  position: relative;
  width: fit-content;
  transition: background var(--transition);
}
.offer-card .btn-offer:hover { background: #0057b8; }
.offer-card.rewards .btn-offer { background: var(--gold); color: var(--dark); }
.offer-card.rewards .btn-offer:hover { background: var(--gold-hover); }

/* PROPERTY TYPES SCROLL */
.property-scroll {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 8px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}
.property-scroll::-webkit-scrollbar { height: 4px; }
.property-scroll::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.property-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
.property-type-chip {
  padding: 10px 20px;
  border-radius: 24px;
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  scroll-snap-align: start;
  transition: all var(--transition);
  color: var(--text);
  background: #fff;
}
.property-type-chip:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* TABS */
.tab-bar {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  margin-bottom: 28px;
  border-bottom: 2px solid var(--border-light);
  padding-bottom: 0;
}
.tab-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--blue); }
.tab-btn.active {
  color: var(--blue);
  border-bottom-color: var(--blue);
  font-weight: 600;
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* DEST CARDS */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.dest-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-md);
}
.dest-card-img {
  width: 64px;
  height: 64px;
  border-radius: 8px;
  background: linear-gradient(135deg, #e8f0fe, #b3d4ff);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}
.dest-card h4 { font-size: 15px; font-weight: 600; }
.dest-card p { font-size: 13px; color: var(--text-light); margin-top: 2px; }

/* CAROUSEL */
.carousel-wrap { position: relative; }
.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 8px 0 16px;
  scroll-behavior: smooth;
}
.carousel::-webkit-scrollbar { height: 4px; }
.carousel::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.carousel::-webkit-scrollbar-thumb { background: #c4c4c4; border-radius: 4px; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #fff;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: all var(--transition);
  border: 1px solid var(--border);
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--bg-soft); }
.carousel-btn.prev { left: -16px; }
.carousel-btn.next { right: -16px; }
.carousel-btn svg { width: 20px; height: 20px; color: var(--text); }

/* PROPERTY CARD */
.property-card {
  min-width: 260px;
  max-width: 260px;
  scroll-snap-align: start;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.property-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.property-card-img {
  height: 180px;
  background: linear-gradient(135deg, #c8d6e5, #8395a7);
  position: relative;
}
.property-card-img .badge-deal {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #00800d;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 4px;
}
.property-card-body { padding: 16px; }
.property-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.property-card-body .location { font-size: 13px; color: var(--text-light); margin-bottom: 10px; }
.property-card-body .rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
}
.rating-badge {
  background: var(--navy);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 6px 6px 6px 0;
}
.rating-text { font-size: 13px; font-weight: 500; }
.rating-count { font-size: 12px; color: var(--text-light); }
.property-card-body .price {
  text-align: right;
  margin-top: 8px;
}
.price .original { text-decoration: line-through; color: var(--text-light); font-size: 13px; margin-right: 6px; }
.price .current { font-size: 18px; font-weight: 700; color: var(--text); }
.price .nights { display: block; font-size: 12px; color: var(--text-light); margin-top: 2px; }

/* TRENDING */
.trending-grid {
  display: flex;
  gap: 16px;
}
.trending-card {
  flex: 1;
  height: 200px;
  border-radius: var(--radius-lg);
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #003B95 0%, #4a7fd4 100%);
  transition: transform var(--transition);
}
.trending-card:hover { transform: scale(1.02); }
.trending-card:nth-child(1) { flex: 2; height: 220px; }
.trending-card:nth-child(2) { flex: 2; height: 220px; }
.trending-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(0,0,0,0.6), transparent);
  color: #fff;
}
.trending-card-content h3 { font-family: var(--font-display); font-size: 20px; font-weight: 700; }
.trending-flag { font-size: 28px; position: absolute; top: 16px; right: 16px; }

/* EXPLORE GRID */
.explore-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.explore-card {
  border-radius: var(--radius);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}
.explore-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.explore-card-img {
  height: 140px;
  background: linear-gradient(135deg, #8395a7, #576574);
  position: relative;
}
.explore-card-body {
  padding: 12px;
  background: #fff;
  border: 1px solid var(--border);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}
.explore-card-body h4 { font-size: 15px; font-weight: 600; }
.explore-card-body p { font-size: 13px; color: var(--text-light); }

/* WEEKEND DEALS / HOMES */
.deals-scroll {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding-bottom: 16px;
  scroll-snap-type: x mandatory;
}
.deals-scroll::-webkit-scrollbar { height: 4px; }
.deals-scroll::-webkit-scrollbar-track { background: var(--border-light); border-radius: 4px; }
.deals-scroll::-webkit-scrollbar-thumb { background: #c4c4c4; border-radius: 4px; }

.deal-card {
  min-width: 280px;
  max-width: 280px;
  scroll-snap-align: start;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.deal-card-img {
  height: 180px;
  background: linear-gradient(135deg, #c8d6e5, #8395a7);
  position: relative;
}
.deal-card-body { padding: 16px; }
.deal-card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 2px; }
.deal-card-body .location { font-size: 13px; color: var(--text-light); margin-bottom: 10px; }
.deal-card-body .rating { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; }
.deal-card-body .duration { font-size: 13px; color: var(--text-secondary); margin-bottom: 6px; }

/* LOYALTY CTA */
.loyalty-section {
  background: linear-gradient(135deg, var(--navy) 0%, #1a4fad 60%, #2563eb 100%);
  padding: 60px 0;
  position: relative;
  overflow: hidden;
}
.loyalty-section::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: rgba(255,255,255,0.04);
}
.loyalty-content {
  max-width: 600px;
  color: #fff;
  position: relative;
}
.loyalty-content h2 {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 800;
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}
.loyalty-content h3 {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 12px;
  opacity: 0.9;
}
.loyalty-content p { font-size: 16px; opacity: 0.85; margin-bottom: 28px; line-height: 1.6; }
.loyalty-actions { display: flex; gap: 12px; }
.btn-gold {
  background: var(--gold);
  color: var(--dark);
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 15px;
  font-weight: 600;
  transition: background var(--transition);
  display: inline-block;
}
.btn-gold:hover { background: var(--gold-hover); }
.btn-white-outline {
  border: 2px solid #fff;
  color: #fff;
  padding: 12px 28px;
  border-radius: 6px;
  font-size: 15px;
  font-weight: 600;
  transition: all var(--transition);
  display: inline-block;
}
.btn-white-outline:hover { background: #fff; color: var(--navy); }

/* POPULAR LINKS */
.popular-links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.popular-links-grid a {
  display: inline-block;
  padding: 8px 16px;
  border: 1px solid var(--border);
  border-radius: 24px;
  font-size: 13px;
  color: var(--text);
  transition: all var(--transition);
}
.popular-links-grid a:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* FOOTER */
.footer {
  background: #0a1628;
  color: #fff;
  padding: 60px 0 30px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: rgba(255,255,255,0.7);
}
.footer-col a {
  display: block;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  text-align: center;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
}

/* BENEFITS */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  background: #fff;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.benefit-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.benefit-card .icon-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: #e8f0fe;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.benefit-card .icon-circle svg { width: 28px; height: 28px; color: var(--blue); }
.benefit-card h3 { font-family: var(--font-display); font-size: 17px; font-weight: 700; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.5; }

/* PACKAGE DEST */
.pkg-dest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.pkg-dest-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  transition: all var(--transition);
  background: #fff;
}
.pkg-dest-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }
.pkg-dest-card-img {
  height: 160px;
  background: linear-gradient(135deg, #4ecdc4, #2d98da);
}
.pkg-dest-card-body { padding: 16px; }
.pkg-dest-card-body h4 { font-size: 16px; font-weight: 600; }
.pkg-dest-card-body .country { font-size: 13px; color: var(--text-light); margin-top: 2px; }
.pkg-dest-card-body .props { font-size: 13px; color: var(--text-secondary); margin-top: 8px; }

/* RENTAL COMPANIES */
.companies-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 16px;
}
.company-card {
  height: 80px;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 16px;
  color: var(--text);
  transition: all var(--transition);
}
.company-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-sm);
}

/* CREDIT CARD PROMO */
.promo-banner {
  background: linear-gradient(135deg, #1a3a4a, #2d5f73);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.promo-banner h3 { font-family: var(--font-display); font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.promo-banner p { opacity: 0.9; font-size: 14px; }
.promo-banner .btn-offer {
  background: var(--gold);
  color: var(--dark);
  padding: 12px 24px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
  transition: background var(--transition);
}
.promo-banner .btn-offer:hover { background: var(--gold-hover); }

/* FAQ ACCORDION */
.faq-list { max-width: 800px; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 20px 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.faq-question:hover { color: var(--blue); }
.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 200px; }
.faq-answer p {
  padding-bottom: 20px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* RENTAL DEST TABLE */
.rental-dest-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.rental-dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  transition: all var(--transition);
}
.rental-dest-card:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-sm);
}
.rental-dest-card-img {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  background: linear-gradient(135deg, #e8f0fe, #b3d4ff);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.rental-dest-info h4 { font-size: 15px; font-weight: 600; }
.rental-dest-info p { font-size: 13px; color: var(--text-light); }
.rental-dest-info .price-tag { font-size: 14px; font-weight: 600; color: var(--blue); margin-top: 2px; }

/* ATTRACTION CARDS */
.activity-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  background: #fff;
  transition: all var(--transition);
}
.activity-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.activity-card-img {
  height: 180px;
  background: linear-gradient(135deg, #ffa502, #ff6348);
  position: relative;
}
.activity-card-body { padding: 16px; }
.activity-card-body h4 { font-size: 14px; font-weight: 600; line-height: 1.4; }

.activity-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

/* NEARBY */
.nearby-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.nearby-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  height: 200px;
  background: linear-gradient(135deg, #576574, #222f3e);
  transition: transform var(--transition);
}
.nearby-card:hover { transform: scale(1.02); }
.nearby-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
  color: #fff;
}
.nearby-card-content h4 { font-family: var(--font-display); font-size: 18px; font-weight: 700; }
.nearby-card-content p { font-size: 13px; opacity: 0.85; }

/* ACCOUNT CTA */
.account-cta {
  background: linear-gradient(135deg, var(--navy) 0%, #1a4fad 100%);
  border-radius: var(--radius-lg);
  padding: 48px;
  color: #fff;
  text-align: center;
}
.account-cta h2 { font-family: var(--font-display); font-size: 32px; font-weight: 800; margin-bottom: 8px; }
.account-cta h3 { font-size: 18px; opacity: 0.9; margin-bottom: 12px; }
.account-cta p { font-size: 15px; opacity: 0.8; margin-bottom: 28px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* PILL LINKS (for popular things to do) */
.pill-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.pill-links a {
  display: inline-block;
  padding: 8px 18px;
  border: 1px solid var(--border);
  border-radius: 24px;
  font-size: 13px;
  transition: all var(--transition);
}
.pill-links a:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: #e8f0fe;
}

/* IMAGE PLACEHOLDERS */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  color: rgba(255,255,255,0.6);
}

/* MOBILE */
@media (max-width: 1024px) {
  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .explore-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .rental-dest-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .hero h1 { font-size: 32px; }
  .hero .subtitle { font-size: 15px; }
  .hero { padding-bottom: 100px; }
  .search-bar { flex-direction: column; }
  .search-bar .field { width: 100%; }
  .search-bar .btn-search { width: 100%; text-align: center; }
  .trust-badges { grid-template-columns: 1fr 1fr; margin-top: -60px; gap: 12px; }
  .trust-badge { padding: 20px 16px; }
  .offers-grid { grid-template-columns: 1fr; }
  .section-title { font-size: 22px; }
  .section-subtitle { font-size: 14px; }
  .trending-grid { flex-direction: column; }
  .trending-card, .trending-card:nth-child(1), .trending-card:nth-child(2) { height: 180px; }
  .explore-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .pkg-dest-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .loyalty-content h2 { font-size: 28px; }
  .promo-banner { flex-direction: column; text-align: center; }
  .radio-group { flex-direction: column; gap: 10px; }
  .companies-grid { grid-template-columns: repeat(3, 1fr); }
  .account-cta { padding: 32px 24px; }
  .account-cta h2 { font-size: 24px; }
  .nearby-grid { grid-template-columns: 1fr; }
  .activity-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-tabs { gap: 2px; }
  .nav-tab { padding: 8px 12px; font-size: 13px; }
  .header-actions .btn-ghost, .header-actions .btn-outline-white { padding: 6px 10px; font-size: 13px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 26px; }
  .trust-badges { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .loyalty-actions { flex-direction: column; }
  .dest-grid { grid-template-columns: 1fr; }
  .activity-grid { grid-template-columns: 1fr; }
}

/* ANIMATIONS */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  animation: fadeInUp 0.5s ease forwards;
  opacity: 0;
}
.animate-in:nth-child(2) { animation-delay: 0.1s; }
.animate-in:nth-child(3) { animation-delay: 0.2s; }
.animate-in:nth-child(4) { animation-delay: 0.3s; }
